const data = items.map(item => item.json);

if (data.length === 0) {
  return [{ json: { error: "Dataset is empty" } }];
}

// Detect numeric columns
const columns = Object.keys(data[0]);

const numericColumns = columns.filter(col => {
  const numericCount = data.filter(row => {
    const value = row[col];
    return value !== "" && !isNaN(parseFloat(value));
  }).length;

  return numericCount > data.length * 0.7;
});

// Choose first meaningful numeric column (skip ID-like)
const targetColumn = numericColumns.find(col =>
  col.toLowerCase() !== "passengerid"
);

if (!targetColumn) {
  return [{ json: { message: "No suitable numeric column for prediction" } }];
}

// Prepare values
const values = data
  .map(row => parseFloat(row[targetColumn]))
  .filter(v => !isNaN(v));

// Simple linear trend prediction
const n = values.length;

let sumX = 0, sumY = 0, sumXY = 0, sumXX = 0;

for (let i = 0; i < n; i++) {
  sumX += i;
  sumY += values[i];
  sumXY += i * values[i];
  sumXX += i * i;
}

const slope = (n * sumXY - sumX * sumY) / (n * sumXX - sumX * sumX);
const intercept = (sumY - slope * sumX) / n;

const nextIndex = n;
const predictedValue = slope * nextIndex + intercept;

return [{
  json: {
    forecastColumn: targetColumn,
    predictedNextValue: Number(predictedValue.toFixed(2))
  }
}];

// Get AI raw output
let raw = items[0].json.output || items[0].json.text || items[0].json.response;

if (!raw) {
  return [{ json: { error: "No AI output found" } }];
}

// Remove markdown + unwanted text
raw = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .replace(/^json/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  return [{
    json: {
      error: "Invalid JSON from AI",
      rawOutput: raw
    }
  }];
}

return [{
  json: parsed
}];

