const data = items[0].json;

// ================= SAFE VALUES =================
const title = data.dashboardTitle || "Enterprise Dashboard";

const totalRows = data.businessKPIs?.totalCustomers || 0;

// Remove % and convert back to number
const survivalRate = data.businessKPIs?.successRate
  ? Number(data.businessKPIs.successRate.replace("%",""))
  : 0;

// Remove $ and convert back to number
const avgFare = data.businessKPIs?.averageRevenue
  ? Number(data.businessKPIs.averageRevenue.replace("$",""))
  : 0;

const estimatedRevenue = data.businessKPIs?.estimatedTotalRevenue
  ? Number(data.businessKPIs.estimatedTotalRevenue.replace("$",""))
  : 0;

const forecast = Number(data.predictedNextValue || 0);



// ===== Sample based quick analytics =====
const sample = data.sampleData || [];

const survivedCount = sample.filter(d => d.Survived == 1).length;
const deadCount = sample.filter(d => d.Survived == 0).length;

const maleCount = sample.filter(d => d.Sex === "male").length;
const femaleCount = sample.filter(d => d.Sex === "female").length;

const class1 = sample.filter(d => d.Pclass == 1).length;
const class2 = sample.filter(d => d.Pclass == 2).length;
const class3 = sample.filter(d => d.Pclass == 3).length;

