  background:#0f172a;
  font-family:Segoe UI;
  color:white;
}

.dashboard{
  width:1280px;
  height:720px;
  margin:auto;
  display:grid;
  grid-template-columns:250px 1fr;
}

.sidebar{
  background:#111827;
  padding:20px;
}

.sidebar h2{
  font-size:18px;
  margin-bottom:30px;
}

.sidebar p{
  color:#94a3b8;
  margin:12px 0;
}

.main{
  padding:20px;
  display:grid;
  grid-template-rows:auto auto 1fr;
  gap:15px;
}

.kpis{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:15px;
}

.card{
  background:#1e293b;
  padding:18px;
  border-radius:10px;
  text-align:center;
}

.card h4{
  margin:0;
  font-size:13px;
  color:#94a3b8;
}

.card .value{
  font-size:26px;
