}

.grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:15px;
}

.box{
  background:#1e293b;
  padding:15px;
  border-radius:10px;
}

.box h3{
  margin-bottom:10px;
  font-size:15px;
}

canvas{
  background:white;
  border-radius:6px;
}
</style>
</head>

<body>

<div class="dashboard">

<div class="sidebar">
